function isIterableValue(value) {
    return (value !== null &&
        value !== undefined &&
        typeof value[Symbol.iterator] === "function");
}
export function flatten_iterable_parameters(args) {
    const flattened_parameters = [];
    for (const arg of args) {
        if (isIterableValue(arg)) {
            for (const item of arg) {
                flattened_parameters.push(item);
            }
        }
        else {
            flattened_parameters.push(arg);
        }
    }
    return flattened_parameters;
}
